#'   `<extra>` is displayed in the secondary box, for example
#'   `<extra>\%\{fullData.name\}</extra>`. To hide the secondary box
#'   completely, use an empty tag `<extra></extra>`. String, or a vector of
#'   these.
#' @param hovertemplatefallback Fallback string that's displayed when a
#'   variable referenced in a template is missing. If the boolean value
#'   'false' is passed in, the specifier with the missing variable will be
#'   displayed. Any value.
#' @param label The shown name of the node. Data array: a vector, factor,
#'   Date/POSIXct vector, matrix or list.
#' @param line A \code{\link{go_sankey_node_line}()} object or named list,
#'   with properties \code{color} and \code{width} (see
#'   \code{\link{go_sankey_node_line}()}).
#' @param pad Sets the padding (in px) between the `nodes`. Number in the
#'   interval [0, Inf].
#' @param sort For `auto` (the default), the vertical order of nodes will
#'   be determined automatically by the layout. For `input`, the vertical
#'   order of nodes is kept the same as the order in the input array. One
#'   of \code{"auto"}, \code{"input"}.
#' @param thickness Sets the thickness (in px) of the `nodes`. Number in
#'   the interval [1, Inf].
#' @param x The normalized horizontal position of the node. Data array: a
#'   vector, factor, Date/POSIXct vector, matrix or list.
#' @param y The normalized vertical position of the node. Data array: a
#'   vector, factor, Date/POSIXct vector, matrix or list.
#' @param ... Not for properties, which must be named in full: an
#'   abbreviated or unknown name is an error that suggests the right one.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_sankey_node} object (a named list).
#'
#' @concept trace objects
#' @noMd
#' @export
#' @examples
#' go_sankey(
#'   node = go_sankey_node(color = "red")
#' )
go_sankey_node <- function(
    ..., align = NULL, color = NULL, customdata = NULL, groups = NULL,
    hoverinfo = NULL, hoverlabel = NULL, hovertemplate = NULL,
    hovertemplatefallback = NULL, label = NULL, line = NULL, pad = NULL,
    sort = NULL, thickness = NULL, x = NULL, y = NULL, skip_invalid = FALSE
) {
  plotly_object("sankey.node", NULL, environment(), list(...), skip_invalid)
}

#' Sankey node line objects
#'
#' The object for the \code{node.line} of a sankey trace
#' (\code{\link{go_sankey_node}()}). \code{go_sankey_node_line()} creates
#' one, with exactly its properties; a named list with the same properties
#' works too.
#'
#' @details
#' Nested objects are named lists, or objects of the constructors their
#' arguments name. Every property is checked against the plotly.js schema
#' when the object is created or modified. A property may be a one-sided
#' formula (\code{color = ~col}): it is kept, and evaluated in the data
#' (then checked) when its trace is added to a figure with
#' \code{add_<trace>()} or \code{add_trace()}.
#'
#' @param color Sets the color of the `line` around each `node`. Color: a
#'   CSS color string or R color name, or a vector of these.
#' @param width Sets the width (in px) of the `line` around each `node`.
#'   Number in the interval [0, Inf], or a vector of these.
#' @param ... Not for properties, which must be named in full: an
#'   abbreviated or unknown name is an error that suggests the right one.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_sankey_node_line} object (a named list).
#'
#' @concept trace objects
#' @noMd
#' @export
#' @examples
#' go_sankey(
#'   node = go_sankey_node(
#'     line = go_sankey_node_line(color = "red")
#'   )
#' )
go_sankey_node_line <- function(
    ..., color = NULL, width = NULL, skip_invalid = FALSE
) {
  plotly_object("sankey.node.line", NULL, environment(), list(...), skip_invalid)
}

